import{_ as s,c as l,o as e,ah as n}from"./chunks/framework.BrJYEL96.js";const d=JSON.parse('{"title":"Gitee","description":"","frontmatter":{},"headers":[],"relativePath":"tools/git/Gitee.md","filePath":"tools/git/Gitee.md","lastUpdated":1789958945000}'),o={name:"tools/git/Gitee.md"};function t(i,a,p,r,c,g){return e(),l("div",null,a[0]||(a[0]=[n(`<h1 id="gitee" tabindex="-1">Gitee <a class="header-anchor" href="#gitee" aria-label="Permalink to &quot;Gitee&quot;">​</a></h1><p><strong>国内的 Git 代码托管平台，对标 GitHub</strong>，由 OSCHINA（开源中国）开发运营，官网：<a href="https://gitee.com/" target="_blank" rel="noreferrer">gitee.com</a></p><blockquote><p>一句话区分： <strong>Git</strong> = 本地版本控制软件（装在电脑上） <strong>Gitee / GitHub</strong> = 云端网站，用来存放、同步、协作管理代码仓库</p></blockquote><h3 id="✅-核心功能" tabindex="-1">✅ 核心功能 <a class="header-anchor" href="#✅-核心功能" aria-label="Permalink to &quot;✅ 核心功能&quot;">​</a></h3><ol><li><strong>代码版本托管</strong>：保存代码历史，随时回退版本；支持公开开源仓库、私有仓库。</li><li><strong>团队协同</strong>：多人一起开发、代码评审、分支管理、提交记录查看。</li><li><strong>配套工具</strong>：在线文档、任务看板、代码扫描、CI/CD 自动部署、云端 IDE 等 DevOps 能力。</li><li><strong>私有化部署</strong>：企业可以部署在自己内网，适合政企对代码安全、国产化有要求的场景Gitee。</li></ol><h3 id="📌-特点" tabindex="-1">📌 特点 <a class="header-anchor" href="#📌-特点" aria-label="Permalink to &quot;📌 特点&quot;">​</a></h3><ul><li>✅ <strong>国内服务器，访问速度快，中文界面</strong>，GitHub 国内访问不稳定时最常用替代平台</li><li>✅ 个人基础功能免费（私有仓库有免费额度），企业高级版收费</li><li>✅ 大量国内开源项目托管在这里，也是学生、开发者常用的代码备份平台</li></ul><h3 id="🧩-常见用途" tabindex="-1">🧩 常见用途 <a class="header-anchor" href="#🧩-常见用途" aria-label="Permalink to &quot;🧩 常见用途&quot;">​</a></h3><ul><li>个人：代码备份、练手项目、作品集</li><li>学生：课程作业、毕业设计代码托管</li><li>团队 / 企业：内部项目协作、开源项目发布</li></ul><h2 id="注册" tabindex="-1">注册 <a class="header-anchor" href="#注册" aria-label="Permalink to &quot;注册&quot;">​</a></h2><ol><li><p>打开 <a href="https://gitee.com/" target="_blank" rel="noreferrer">gitee.com</a></p></li><li><p>点击注册</p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/13/70100_reg.png" alt="reg" style="zoom:80%;"></li><li><p>上传头像后一路下一步直到进入到工作台</p></li></ol><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/20/19524_image-20260919205318775.png" alt="图片" loading="lazy"></p><ol start="4"><li>鼠标移动到头像上，点击账号设置</li></ol><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/20522_image-20260919210136387.png" alt="image-20260919210136387" loading="lazy"></p><ol start="5"><li><p>绑定第三方账号，任选一个即可</p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/67381_image-20260919210321684.png" alt="" loading="lazy"></p></li><li><p>设置邮箱</p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/37583_image-20260919210639769.png" alt="image-20260919210639769" loading="lazy"></p></li></ol><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/31324_image-20260919210822306.png" alt="image-20260919210822306" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/92485_image-20260919210849282.png" alt="image-20260919210849282" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/98136_image-20260919211002371.png" alt="image-20260919211002371" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/38916_image-20260919211120299.png" alt="image-20260919211120299" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/50473_image-20260919211245396.png" alt="image-20260919211245396" loading="lazy"></p><ol start="7"><li>创建项目</li></ol><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/34152_image-20260919211437807.png" alt="image-20260919211437807" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/19909_image-20260919211726765.png" alt="image-20260919211726765" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/74816_image-20260919211757662.png" alt="image-20260919211757662" loading="lazy"></p><ol start="8"><li>添加协作开发者，需要共同开发者提供Gitee协作账号</li></ol><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/8364_image-20260919212103765.png" alt="image-20260919212103765" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/97417_image-20260919212144256.png" alt="image-20260919212144256" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/53666_image-20260919212209023.png" alt="image-20260919212209023" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/39090_image-20260919212505405.png" alt="image-20260919212505405" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/6597_image-20260919212736700.png" alt="image-20260919212736700" loading="lazy"></p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-19/21/8570_image-20260919212804584.png" alt="image-20260919212804584" loading="lazy"></p><ol start="9"><li><p>个人仓库地址</p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-09-20/20/87396_image-20260920204157498.png" alt="image-20260920204157498" loading="lazy"></p></li></ol><h4 id="简易的命令行入门教程" tabindex="-1">简易的命令行入门教程: <a class="header-anchor" href="#简易的命令行入门教程" aria-label="Permalink to &quot;简易的命令行入门教程:&quot;">​</a></h4><p><a href="https://www.runoob.com/git/git-basic-operations.html" target="_blank" rel="noreferrer">Git学习教程</a></p><p>Git 全局设置:</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#7F848E;font-style:italic;"># 安装软件后仅执行一次</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> config</span><span style="color:#D19A66;"> --global</span><span style="color:#98C379;"> user.name</span><span style="color:#98C379;"> &quot;班级+姓名&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> config</span><span style="color:#D19A66;"> --global</span><span style="color:#98C379;"> user.email</span><span style="color:#98C379;"> &quot;邮箱&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>创建 git 仓库:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#7F848E;font-style:italic;"># 初始化仓库后首次提交</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> init</span><span style="color:#7F848E;font-style:italic;"> # 初始化仓库</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> .</span><span style="color:#7F848E;font-style:italic;"> # 将代码从工作区提价到暂存区</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> commit</span><span style="color:#D19A66;"> -m</span><span style="color:#98C379;"> &quot;备注信息&quot;</span><span style="color:#7F848E;font-style:italic;"> # 将代码从暂存区提交到本地仓库</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> remote</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> origin</span><span style="color:#98C379;"> https://gitee.com/用户名/仓库.git</span><span style="color:#7F848E;font-style:italic;">  #第一次提交执行，关联仓库</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> push</span><span style="color:#D19A66;"> -u</span><span style="color:#98C379;"> origin</span><span style="color:#98C379;"> master</span><span style="color:#7F848E;font-style:italic;"> # 第一次从本地仓库向远端仓库推送</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>已有仓库</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> existing_git_repo</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> remote</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> origin</span><span style="color:#98C379;"> https://gitee.com/用户名/仓库.git</span><span style="color:#7F848E;font-style:italic;"> #第一次提交执行，关联仓库</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> push</span><span style="color:#D19A66;"> -u</span><span style="color:#98C379;"> origin</span><span style="color:#98C379;"> master</span><span style="color:#7F848E;font-style:italic;"> # 第一次从本地仓库向远端仓库推送</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>第二次及以后提交后直接推送</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> .</span><span style="color:#7F848E;font-style:italic;"> # 将代码从工作区提价到暂存区</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> commit</span><span style="color:#D19A66;"> -m</span><span style="color:#98C379;"> &quot;备注信息&quot;</span><span style="color:#7F848E;font-style:italic;"> # 将代码从暂存区提交到本地仓库</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> push</span><span style="color:#7F848E;font-style:italic;"> # 直接推送到远端</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>从远端仓库克隆代码</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> clone</span><span style="color:#98C379;"> https://gitee.com/用户名/仓库.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="授权验证" tabindex="-1">授权验证 <a class="header-anchor" href="#授权验证" aria-label="Permalink to &quot;授权验证&quot;">​</a></h4><p>使用 HTTPS 协议时，命令行会出现如下账号密码验证步骤。基于安全考虑，Gitee 建议<a href="https://gitee.com/profile/personal_access_tokens" target="_blank" rel="noreferrer"> 配置并使用私人令牌 </a>替代登录密码进行克隆、推送等操作</p><p>Username for &#39;<a href="https://gitee.com" target="_blank" rel="noreferrer">https://gitee.com</a>&#39;: 用户名</p><p>Password for &#39;<a href="https://%E7%94%A8%E6%88%B7%E5%90%8D@gitee.com" target="_blank" rel="noreferrer">https://用户名@gitee.com</a>&#39;: 私人令牌或者密码（命令行输入密码时不显示）</p>`,48)]))}const y=s(o,[["render",t]]);export{d as __pageData,y as default};
